        if ($endpoint==='auth') $this->auth($parts[2]??'', $method);
        if ($endpoint==='setup') $this->setup($method);
        if ($endpoint==='lead-capture' || $endpoint==='lead_capture.php') $this->leadCapture($method);
        if ($endpoint==='notifications') $this->notifications($parts[2]??'', $method);
        if ($endpoint==='notification_poll.php') $this->notifications('poll',$method);
        if ($endpoint==='dashboard') $this->dashboard();
        if ($endpoint==='search') $this->search();
        if ($endpoint==='timeline') $this->timeline($parts[2]??'',(int)($parts[3]??0));
        if ($endpoint==='roles' && ($parts[3]??'')==='permissions') $this->rolePermissions((int)($parts[2]??0),$method);
        if ($endpoint==='reports') $this->reports($parts[2]??'');
        if ($endpoint==='deals' && ($parts[3]??'')==='convert-stage') $this->moveDeal((int)($parts[2]??0),$method);
        if ($endpoint==='deals' && ($parts[3]??'')==='quote') $this->quoteFromDeal((int)($parts[2]??0),$method);
        if ($endpoint==='quotes' && ($parts[3]??'')==='invoice') $this->invoiceFromQuote((int)($parts[2]??0),$method);
        if ($endpoint==='invoices' && ($parts[3]??'')==='send') $this->sendInvoice((int)($parts[2]??0),$method);
        if ($endpoint==='leads' && ($parts[3]??'')==='convert') $this->convertLead((int)($parts[2]??0),$method);
        if ($endpoint==='invoices' && ($parts[3]??'')==='pdf') $this->invoicePdf((int)($parts[2]??0));
        if ($endpoint==='quotes' && ($parts[3]??'')==='pdf') $this->quotePdf((int)($parts[2]??0));
        if ($endpoint==='invoices' && ($parts[3]??'')==='payments') $this->recordPayment((int)($parts[2]??0),$method);
        if ($endpoint==='smtp') $this->smtp($method);
        if ($endpoint==='company-settings') $this->companySettings($method);
