    }
    private function auth(string $action,string $method): never {
        if ($action==='csrf' && $method==='GET') Response::ok(['token'=>Auth::csrfToken()]);
        if ($action==='session' && $method==='GET') { $u=Auth::user(); if($u)$u=Auth::requireUser(); Response::ok(['authenticated'=>(bool)$u,'user'=>Auth::withPermissions($u),'csrf'=>Auth::csrfToken()]); }
        if ($action==='register') $this->register($method);
        if ($action==='login' && $method==='POST') {
            Auth::verifyCsrf(); $b=Request::body(); Validator::required($b,['email','password','tenant']); Validator::email((string)$b['email']);
            $workspace=$this->db->prepare("SELECT id FROM tenants WHERE slug=? AND status='active' LIMIT 1");
            $workspace->execute([strtolower(trim((string)$b['tenant']))]);$tenantId=(int)$workspace->fetchColumn();
            if (!$tenantId) Response::error('Workspace not found.',404,['tenant'=>'Check the workspace slug.']);
            $q=$this->db->prepare('SELECT id,tenant_id,full_name,email,password_hash,role,status FROM users WHERE tenant_id=? AND email=? LIMIT 1');
            $q->execute([$tenantId,strtolower(trim((string)$b['email']))]); $u=$q->fetch();
            if (!$u || $u['status']!=='Active' || !Password::verify((string)$b['password'],$u['password_hash'])) Response::error('Invalid email or password.',401,['credentials'=>'Check your email and password.']);
            $tenant=$this->db->prepare("SELECT name tenant_name,timezone FROM tenants WHERE id=? AND status='active' LIMIT 1");$tenant->execute([$tenantId]);$details=$tenant->fetch();
            if(!$details)Response::error('Workspace not found.',404,['tenant'=>'Check the workspace slug.']);
            $u=array_merge($u,$details);
            session_regenerate_id(true); unset($u['password_hash']); $_SESSION['user']=$u; $_SESSION['csrf']=bin2hex(random_bytes(32));
            $this->db->prepare('UPDATE users SET last_login_at=NOW() WHERE id=? AND tenant_id=?')->execute([$u['id'],$u['tenant_id']]);
            Response::ok(['user'=>Auth::withPermissions($u),'csrf'=>Auth::csrfToken()]);
        }
        if ($action==='logout' && $method==='POST') { Auth::requireUser(); Auth::verifyCsrf(); $_SESSION=[]; session_regenerate_id(true); Response::ok(['logged_out'=>true]); }
        Response::error('Route not found.',404);
    }
