    private function convertLead(int $id,string $method): never {
        if($method!=='POST')Response::error('Method not allowed.',405);$u=Auth::requirePermission('leads.manage');Auth::verifyCsrf();$q=$this->db->prepare('SELECT * FROM leads WHERE tenant_id=? AND id=? FOR UPDATE');$this->db->beginTransaction();try{$q->execute([$u['tenant_id'],$id]);$lead=$q->fetch();if(!$lead)Response::error('Lead not found.',404);if($lead['converted_deal_id'])Response::ok(['contact_id'=>$lead['converted_contact_id'],'account_id'=>$lead['converted_account_id'],'deal_id'=>$lead['converted_deal_id'],'already_converted'=>true]);if($lead['lead_status']!=='Qualified')Response::error('Only qualified leads can be converted.',422);
            $account=null;if($lead['company']){$find=$this->db->prepare('SELECT id FROM accounts WHERE tenant_id=? AND company_name=? LIMIT 1');$find->execute([$u['tenant_id'],$lead['company']]);$account=$find->fetchColumn();if(!$account){$this->db->prepare('INSERT INTO accounts(tenant_id,company_name,phone,website,created_by) VALUES(?,?,?,?,?)')->execute([$u['tenant_id'],$lead['company'],$lead['phone'],$lead['website'],$u['id']]);$account=(int)$this->db->lastInsertId();}}
            $this->db->prepare('INSERT INTO contacts(tenant_id,account_id,first_name,last_name,email,phone,assigned_to,created_by) VALUES(?,?,?,?,?,?,?,?)')->execute([$u['tenant_id'],$account,$lead['first_name'],$lead['last_name'],$lead['email'],$lead['phone'],$lead['assigned_to'],$u['id']]);$contact=(int)$this->db->lastInsertId();$pipe=$this->db->prepare('SELECT id FROM pipelines WHERE tenant_id=? AND is_default=1 ORDER BY id LIMIT 1');$pipe->execute([$u['tenant_id']]);$pipeline=(int)$pipe->fetchColumn();$stage=$this->db->prepare('SELECT id FROM pipeline_stages WHERE tenant_id=? AND pipeline_id=? ORDER BY position LIMIT 1');$stage->execute([$u['tenant_id'],$pipeline]);$stageId=(int)$stage->fetchColumn();if(!$pipeline||!$stageId)Response::error('Default pipeline is not configured.',409);
            $this->db->prepare('INSERT INTO deals(tenant_id,deal_title,pipeline_id,stage_id,contact_id,account_id,source_lead_id,amount,assigned_to,team_id,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?)')->execute([$u['tenant_id'],trim($lead['first_name'].' '.$lead['last_name']).' - Opportunity',$pipeline,$stageId,$contact,$account,$id,$lead['lead_value'],$lead['assigned_to'],$lead['team_id'],$u['id']]);$deal=(int)$this->db->lastInsertId();$this->db->prepare("UPDATE leads SET lead_status='Qualified',converted_contact_id=?,converted_account_id=?,converted_deal_id=?,converted_at=NOW() WHERE tenant_id=? AND id=?")->execute([$contact,$account,$deal,$u['tenant_id'],$id]);$this->db->commit();Response::ok(['contact_id'=>$contact,'account_id'=>$account,'deal_id'=>$deal],201);
        }catch(\Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}
    }
    private function recordPayment(int $invoiceId,string $method): never {
        if($method!=='POST')Response::error('Method not allowed.',405);$u=Auth::requirePermission('billing.manage');Auth::verifyCsrf();$b=Request::body();Validator::required($b,['amount','payment_date']);$amount=Validator::money($b['amount'],'amount');$paymentDate=UtcTime::normalize($b['payment_date'],$this->tenantTimezone((int)$u['tenant_id']),'payment_date');$this->db->beginTransaction();try{$q=$this->db->prepare('SELECT * FROM invoices WHERE tenant_id=? AND id=? FOR UPDATE');$q->execute([$u['tenant_id'],$invoiceId]);$invoice=$q->fetch();if(!$invoice)Response::error('Invoice not found.',404);if((float)$amount>(float)$invoice['balance_due'])Response::error('Payment exceeds remaining invoice balance.',422);$this->db->prepare('INSERT INTO payments(tenant_id,invoice_id,amount,currency,payment_date,method,reference,notes,recorded_by) VALUES(?,?,?,?,?,?,?,?,?)')->execute([$u['tenant_id'],$invoiceId,$amount,$invoice['currency'],$paymentDate,$b['method']??null,$b['reference']??null,$b['notes']??null,$u['id']]);$paid=round((float)$invoice['paid_amount']+(float)$amount,2);$balance=round((float)$invoice['grand_total']-$paid,2);$status=$balance<=0?'Paid':($paid>0?'Partially Paid':$invoice['status']);$this->db->prepare('UPDATE invoices SET paid_amount=?,balance_due=?,status=? WHERE tenant_id=? AND id=?')->execute([$paid,$balance,$status,$u['tenant_id'],$invoiceId]);$this->db->commit();Response::ok(['paid_amount'=>number_format($paid,2,'.',''),'balance_due'=>number_format(max(0,$balance),2,'.',''),'status'=>$status]);}catch(\Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}
    }
    private function sendInvoice(int $id,string $method): never {if($method!=='POST')Response::error('Method not allowed.',405);$u=Auth::requirePermission('billing.manage');Auth::verifyCsrf();$q=$this->db->prepare("UPDATE invoices SET status='Sent' WHERE tenant_id=? AND id=? AND status='Draft'");$q->execute([$u['tenant_id'],$id]);if(!$q->rowCount())Response::error('Invoice not found or is not a draft.',409);Response::ok(['status'=>'Sent']);}
    private function smtp(string $method): never {
        $u=Auth::requirePermission('settings.manage');if($method==='GET'){$q=$this->db->prepare('SELECT host,port,username,encryption,from_email,from_name,is_configured FROM smtp_settings WHERE tenant_id=?');$q->execute([$u['tenant_id']]);Response::ok($q->fetch()?:['is_configured'=>false]);}
        if(!in_array($method,['POST','PUT'],true))Response::error('Method not allowed.',405);Auth::verifyCsrf();$b=Request::body();Validator::required($b,['host','port','from_email','from_name']);Validator::email($b['from_email']);$existing=$this->db->prepare('SELECT id,password_encrypted FROM smtp_settings WHERE tenant_id=?');$existing->execute([$u['tenant_id']]);$old=$existing->fetch();$secret=trim((string)($b['password']??''));$encrypted=$secret!==''?SmtpCipher::encrypt($secret,(string)\HaCrm\Core\Config::get('APP_KEY','')):($old['password_encrypted']??null);$vals=[$b['host'],(int)$b['port'],$b['username']??null,$encrypted,$b['encryption']??'tls',$b['from_email'],$b['from_name'],$encrypted?1:0,$u['tenant_id']];$this->db->prepare('INSERT INTO smtp_settings(host,port,username,password_encrypted,encryption,from_email,from_name,is_configured,tenant_id) VALUES(?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE host=VALUES(host),port=VALUES(port),username=VALUES(username),password_encrypted=VALUES(password_encrypted),encryption=VALUES(encryption),from_email=VALUES(from_email),from_name=VALUES(from_name),is_configured=VALUES(is_configured)')->execute($vals);Response::ok(['is_configured'=>(bool)$encrypted]);
    }
    private function companySettings(string $method): never {
        $u=Auth::requirePermission($method==='GET'?'settings.view':'settings.manage');$q=$this->db->prepare('SELECT * FROM company_settings WHERE tenant_id=?');$q->execute([$u['tenant_id']]);if($method==='GET')Response::ok($q->fetch()?:[]);if(!in_array($method,['POST','PUT'],true))Response::error('Method not allowed.',405);Auth::verifyCsrf();$b=Request::body();$data=Validator::fields($b,['company_name','registration_number','tax_id','address','phone','website']);$this->db->prepare('INSERT INTO company_settings(tenant_id,company_name,registration_number,tax_id,address,phone,website) VALUES(?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE company_name=VALUES(company_name),registration_number=VALUES(registration_number),tax_id=VALUES(tax_id),address=VALUES(address),phone=VALUES(phone),website=VALUES(website)')->execute([$u['tenant_id'],$data['company_name']??null,$data['registration_number']??null,$data['tax_id']??null,$data['address']??null,$data['phone']??null,$data['website']??null]);Response::ok(['updated'=>true]);
    }
    private function rolePermissions(int $roleId,string $method): never {
        $u=Auth::requirePermission($method==='GET'?'users.view':'users.manage');$role=$this->db->prepare('SELECT id,name FROM roles WHERE tenant_id=? AND id=?');$role->execute([$u['tenant_id'],$roleId]);$r=$role->fetch();if(!$r)Response::error('Role not found.',404);
        if($method==='GET'){$q=$this->db->prepare('SELECT p.id,p.permission_key,p.label,(rp.permission_id IS NOT NULL) enabled FROM permissions p LEFT JOIN role_permissions rp ON rp.permission_id=p.id AND rp.role_id=? ORDER BY p.permission_key');$q->execute([$roleId]);Response::ok(['role'=>$r,'permissions'=>$q->fetchAll()]);}
        if($method!=='PUT')Response::error('Method not allowed.',405);Auth::verifyCsrf();$b=Request::body();if(!isset($b['permission_ids'])||!is_array($b['permission_ids']))Response::error('permission_ids array is required.',422);$ids=array_values(array_unique(array_filter(array_map('intval',$b['permission_ids']),fn($x)=>$x>0)));$this->db->beginTransaction();try{$this->db->prepare('DELETE FROM role_permissions WHERE role_id=?')->execute([$roleId]);$insert=$this->db->prepare('INSERT INTO role_permissions(role_id,permission_id) SELECT ?,id FROM permissions WHERE id=?');foreach($ids as $permissionId)$insert->execute([$roleId,$permissionId]);$this->db->commit();Response::ok(['updated'=>true]);}catch(\Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}
    }
    private function notifications(string $action,string $method): never {
        $u=Auth::requireUser();if($action==='poll'&&$method==='GET'){$since=max(0,(int)($_GET['since']??0));$q=$this->db->prepare('SELECT id,notification_type,title,body,entity_type,entity_id,read_at,created_at FROM notifications WHERE tenant_id=? AND user_id=? AND id>? ORDER BY id LIMIT 50');$q->execute([$u['tenant_id'],$u['id'],$since]);Response::ok($q->fetchAll());}
        if($action==='read'&&$method==='POST'){Auth::verifyCsrf();$b=Request::body();if(isset($b['id']))$this->db->prepare('UPDATE notifications SET read_at=NOW() WHERE tenant_id=? AND user_id=? AND id=?')->execute([$u['tenant_id'],$u['id'],$b['id']]);else$this->db->prepare('UPDATE notifications SET read_at=NOW() WHERE tenant_id=? AND user_id=? AND read_at IS NULL')->execute([$u['tenant_id'],$u['id']]);Response::ok(['updated'=>true]);}Response::error('Route not found.',404);
    }
    private function leadCapture(string $method): never {
        if($method!=='POST')Response::error('Method not allowed.',405);$b=Request::body();Validator::required($b,['tenant','first_name','last_name','email','phone']);Validator::email((string)$b['email']);if(!empty($b['fax']))Response::ok(['accepted'=>true],202);
        $q=$this->db->prepare("SELECT id FROM tenants WHERE slug=? AND status='active'");$q->execute([$b['tenant']]);$tenant=(int)$q->fetchColumn();if(!$tenant)Response::error('Workspace not found.',404);
        $appKey=(string)\HaCrm\Core\Config::get('APP_KEY','local-development-key');$ipHash=hash_hmac('sha256',(string)($_SERVER['REMOTE_ADDR']??'unknown'),$appKey);$lim=$this->db->prepare('INSERT INTO lead_capture_limits(tenant_id,ip_hash,window_started_at,submissions) VALUES(?,?,NOW(),1) ON DUPLICATE KEY UPDATE submissions=IF(window_started_at<DATE_SUB(NOW(),INTERVAL 1 MINUTE),1,submissions+1),window_started_at=IF(window_started_at<DATE_SUB(NOW(),INTERVAL 1 MINUTE),NOW(),window_started_at)');$lim->execute([$tenant,$ipHash]);$checkLimit=$this->db->prepare('SELECT submissions FROM lead_capture_limits WHERE tenant_id=? AND ip_hash=?');$checkLimit->execute([$tenant,$ipHash]);if((int)$checkLimit->fetchColumn()>10)Response::error('Too many submissions. Try again later.',429);
        $this->db->beginTransaction();try{$users=$this->db->prepare("SELECT id,email FROM users WHERE tenant_id=? AND status='Active' AND eligible_for_leads=1 AND role='Sales Rep' ORDER BY id FOR UPDATE");$users->execute([$tenant]);$eligible=$users->fetchAll();$ids=array_map('intval',array_column($eligible,'id'));$assigned=null;$repEmail=null;if($ids){$c=$this->db->prepare('SELECT cursor_user_id FROM lead_assignment_cursors WHERE tenant_id=? FOR UPDATE');$c->execute([$tenant]);$last=(int)$c->fetchColumn();$idx=array_search($last,$ids,true);$assigned=$ids[($idx===false?0:($idx+1)%count($ids))];foreach($eligible as $rep)if((int)$rep['id']===$assigned)$repEmail=$rep['email'];$this->db->prepare('INSERT INTO lead_assignment_cursors(tenant_id,cursor_user_id) VALUES(?,?) ON DUPLICATE KEY UPDATE cursor_user_id=VALUES(cursor_user_id)')->execute([$tenant,$assigned]);}$insert=$this->db->prepare("INSERT INTO leads(tenant_id,first_name,last_name,email,phone,company,lead_source,lead_status,assigned_to) VALUES(?,?,?,?,?,?,?,'New',?)");$insert->execute([$tenant,mb_substr(trim($b['first_name']),0,80),mb_substr(trim($b['last_name']),0,80),strtolower(trim($b['email'])),mb_substr(trim($b['phone']),0,30),isset($b['company'])?mb_substr(trim($b['company']),0,150):null,'Website Form',$assigned]);$id=(int)$this->db->lastInsertId();if($assigned){$this->db->prepare("INSERT INTO notifications(tenant_id,user_id,notification_type,title,body,idempotency_key) VALUES(?,?,'lead_assigned','New lead assigned',?,?)")->execute([$tenant,$assigned,'A new web lead has been assigned.','lead-'.$id]);if($repEmail)$this->db->prepare("INSERT IGNORE INTO email_outbox(tenant_id,event_key,recipient,subject,body) VALUES(?,?,?,'New lead assigned','A new web lead has been assigned to you.')")->execute([$tenant,'lead-assigned:'.$id,$repEmail]);}$this->db->commit();Response::ok(['id'=>$id,'assigned'=>!!$assigned],201);}catch(\Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}
    }
    private function invoicePdf(int $id): never {
        $u=Auth::requirePermission('billing.view');$q=$this->db->prepare('SELECT i.*,a.company_name, c.first_name,c.last_name,c.email FROM invoices i LEFT JOIN accounts a ON a.id=i.account_id AND a.tenant_id=i.tenant_id LEFT JOIN contacts c ON c.id=i.contact_id AND c.tenant_id=i.tenant_id WHERE i.tenant_id=? AND i.id=?');$q->execute([$u['tenant_id'],$id]);$invoice=$q->fetch();if(!$invoice)Response::error('Invoice not found.',404);$items=$this->db->prepare('SELECT item_name,description,quantity,unit_price,tax_rate,item_total FROM invoice_items WHERE tenant_id=? AND invoice_id=?');$items->execute([$u['tenant_id'],$id]);$rows=$items->fetchAll();if(!class_exists('FPDF'))Response::error('PDF library unavailable. Run composer install.',503);$pdf=new \FPDF();$pdf->AddPage();$pdf->SetFont('Arial','B',18);$pdf->Cell(0,12,'HA CRM - Invoice '.$invoice['invoice_number'],0,1);$pdf->SetFont('Arial','',11);$pdf->Cell(0,8,'Bill to: '.($invoice['company_name']?:trim(($invoice['first_name']??'').' '.($invoice['last_name']??''))),0,1);$pdf->Cell(0,8,'Issue date: '.$invoice['issue_date'].'  Due: '.$invoice['due_date'],0,1);$pdf->Ln(5);foreach($rows as $it)$pdf->MultiCell(0,7,$it['item_name'].' | Qty '.$it['quantity'].' | '.$invoice['currency'].' '.$it['item_total']);$pdf->Ln(5);$pdf->Cell(0,8,'Grand total: '.$invoice['currency'].' '.number_format((float)$invoice['grand_total'],2),0,1);header('Content-Type: application/pdf');$pdf->Output('D','invoice-'.$invoice['invoice_number'].'.pdf');exit;
    }
    private function quotePdf(int $id): never {$u=Auth::requirePermission('billing.view');$q=$this->db->prepare('SELECT q.*,a.company_name,c.first_name,c.last_name FROM quotes q LEFT JOIN accounts a ON a.id=q.account_id AND a.tenant_id=q.tenant_id LEFT JOIN contacts c ON c.id=q.contact_id AND c.tenant_id=q.tenant_id WHERE q.tenant_id=? AND q.id=?');$q->execute([$u['tenant_id'],$id]);$doc=$q->fetch();if(!$doc)Response::error('Quote not found.',404);$items=$this->db->prepare('SELECT item_name,description,quantity,unit_price,tax_rate,item_total FROM quote_items WHERE tenant_id=? AND quote_id=?');$items->execute([$u['tenant_id'],$id]);if(!class_exists('FPDF'))Response::error('PDF library unavailable. Run composer install.',503);$pdf=new \FPDF();$pdf->AddPage();$pdf->SetFont('Arial','B',18);$pdf->Cell(0,12,'HA CRM - Quote '.$doc['quote_number'],0,1);$pdf->SetFont('Arial','',11);$pdf->Cell(0,8,'Prepared for: '.($doc['company_name']?:trim(($doc['first_name']??'').' '.($doc['last_name']??''))),0,1);$pdf->Cell(0,8,'Issue date: '.$doc['issue_date'].'  Valid until: '.($doc['due_date']??'N/A'),0,1);$pdf->Ln(5);foreach($items->fetchAll() as $it)$pdf->MultiCell(0,7,$it['item_name'].' | Qty '.$it['quantity'].' | '.$doc['currency'].' '.$it['item_total']);$pdf->Ln(5);$pdf->Cell(0,8,'Grand total: '.$doc['currency'].' '.number_format((float)$doc['grand_total'],2),0,1);header('Content-Type: application/pdf');$pdf->Output('D','quote-'.$doc['quote_number'].'.pdf');exit;}
